{"command": "str_replace", "new_str": "impl Parser<'_> {
    /// Parses the input string into a SQL statement AST. The entire string must
    /// be parsed as a single statement, ending with an optional semicolon.
    pub fn parse(statement: &str) -> Result<ast::Statement> {
        let mut parser = Parser::new(statement);
        let stmt = parser.parse_statement()?;
        parser.expect(Token::Semicolon)?;
        Ok(stmt)
    }

    /// Parse the input string into a SQL expression AST. The entire string must
    /// be parsed as a single expression. Only used in tests.
    #[cfg(test)]
    pub fn parse_expr(expr: &str) -> Result<ast::Expression> {
        let mut parser = Parser::new(expr);
        let expr = parser.parse_expression()?;
        if parser.lexer.peek().is_some() {
            return Err(errinput!("expected end of expression"));
        }
        Ok(expr)
    }

    /// Creates a new parser for the given raw SQL string.
    fn new(input: &str) -> Parser<'_> {
        Parser {
            lexer: Lexer::new(input).peekable(),
        }
    }

    /// Fetches the next lexer token, or errors if none is found.
    fn next(&mut self) -> Result<Token> {
        self.lexer.next().ok_or_else(|| errinput!("unexpected end of input"))?
    }

    /// Returns the next identifier, or errors if not found.
    fn next_ident(&mut self) -> Result<String> {
        match self.next()? {
            Token::Ident(s) => Ok(s),
            Token::Keyword(k) => Err(errinput!("expected identifier, found keyword {}", k)),
            t => Err(errinput!("expected identifier, found {}", t)),
        }
    }

    /// Returns the next lexer token if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
        self.lexer.next_if(|t| predicate(t))
    }

    /// Passes the next lexer token through the closure, consuming it if the
    /// closure returns Some. Returns the result of the closure.
    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
        self.lexer.next_if_map(f)
    }

    /// Returns the next keyword if there is one.
    fn next_if_keyword(&mut self) -> Option<Keyword> {
        self.next_if_map(|t| match t {
            Token::Keyword(k) => Some(k),
            _ => None,
        })
    }

    /// Consumes the next lexer token if it is the given token, returning true.
    fn next_is(&mut self, token: Token) -> bool {
        self.next_if(|t| *t == token).is_some()
    }

    /// Consumes the next lexer token if it's the expected token, or errors.
    fn expect(&mut self, expect: Token) -> Result<()> {
        match self.next()? {
            t if t == expect => Ok(()),
            t => Err(errinput!("expected {:?}, found {}", expect, t)),
        }
    }

    /// Consumes the next lexer token if it is the given token. Equivalent to
    /// next_is(), but expresses intent better.
    fn skip(&mut self, token: Token) {
        self.next_is(token);
    }

    /// Peeks the next lexer token if any, but transposes it for convenience.
    fn peek(&mut self) -> Result<Option<&Token>> {
        Ok(self.lexer.peek())
    }

    /// Parses a SQL statement.
    fn parse_statement(&mut self) -> Result<ast::Statement> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Begin => self.parse_begin(),
                Keyword::Commit => self.parse_commit(),
                Keyword::Rollback => self.parse_rollback(),
                Keyword::Explain => self.parse_explain(),
                Keyword::Create => self.parse_create_table(),
                Keyword::Drop => self.parse_drop_table(),
                Keyword::Delete => self.parse_delete(),
                Keyword::Insert => self.parse_insert(),
                Keyword::Update => self.parse_update(),
                Keyword::Select => self.parse_select(),
                _ => Err(errinput!("unexpected keyword {}", kw)),
            }
        } else {
            Err(errinput!("expected SQL statement"))
        }
    }

    /// Parses a BEGIN statement.
    fn parse_begin(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Begin))?;
        Ok(ast::Statement::Begin)
    }

    /// Parses a COMMIT statement.
    fn parse_commit(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Commit))?;
        Ok(ast::Statement::Commit)
    }

    /// Parses a ROLLBACK statement.
    fn parse_rollback(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Rollback))?;
        Ok(ast::Statement::Rollback)
    }

    /// Parses an EXPLAIN statement.
    fn parse_explain(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Explain))?;
        let stmt = self.parse_statement()?;
        Ok(ast::Statement::Explain(Box::new(stmt)))
    }

    /// Parses a CREATE TABLE statement.
    fn parse_create_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Create))?;
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        self.expect(Token::OpenParen)?;
        let mut columns = Vec::new();
        let mut first = true;
        while !self.next_is(Token::CloseParen) {
            if !first {
                self.expect(Token::Comma)?;
            }
            first = false;
            columns.push(self.parse_create_table_column()?);
        }
        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    /// Parses a CREATE TABLE column definition.
    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let data_type = self.parse_data_type()?;
        let mut nullable = true;
        let mut default = None;
        while let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Null => {
                    if self.next_is(Token::Keyword(Keyword::Not)) {
                        nullable = false;
                    }
                }
                Keyword::Default => {
                    default = Some(self.parse_expression()?);
                }
                _ => {
                    return Err(errinput!("unexpected keyword {}", kw));
                }
            }
        }
        Ok(ast::Column {
            name,
            data_type,
            nullable,
            default,
        })
    }

    /// Parses a DROP TABLE statement.
    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Drop))?;
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        Ok(ast::Statement::DropTable { name })
    }

    /// Parses a DELETE statement.
    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Delete))?;
        self.expect(Token::Keyword(Keyword::From))?;
        let table = self.next_ident()?;
        let where_clause = self.parse_where_clause()?;
        Ok(ast::Statement::Delete { table, where_clause })
    }

    /// Parses an INSERT statement.
    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Insert))?;
        self.expect(Token::Keyword(Keyword::Into))?;
        let table = self.next_ident()?;
        self.expect(Token::OpenParen)?;
        let mut columns = Vec::new();
        let mut first = true;
        while !self.next_is(Token::CloseParen) {
            if !first {
                self.expect(Token::Comma)?;
            }
            first = false;
            columns.push(self.next_ident()?);
        }
        self.expect(Token::CloseParen)?;
        self.expect(Token::Keyword(Keyword::Values))?;
        self.expect(Token::OpenParen)?;
        let mut values = Vec::new();
        first = true;
        while !self.next_is(Token::CloseParen) {
            if !first {
                self.expect(Token::Comma)?;
            }
            first = false;
            values.push(self.parse_expression()?);
        }
        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::Insert {
            table,
            columns,
            values,
        })
    }

    /// Parses an UPDATE statement.
    fn parse_update(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Update))?;
        let table = self.next_ident()?;
        self.expect(Token::Keyword(Keyword::Set))?;
        let mut assignments = Vec::new();
        let mut first = true;
        while !self.next_is(Token::Where) {
            if !first {
                self.expect(Token::Comma)?;
            }
            first = false;
            let column = self.next_ident()?;
            self.expect(Token::Equal)?;
            assignments.push((column, self.parse_expression()?));
        }
        let where_clause = self.parse_where_clause()?;
        Ok(ast::Statement::Update {
            table,
            assignments,
            where_clause,
        })
    }

    /// Parses a SELECT statement.
    fn parse_select(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Select))?;
        let select_clause = self.parse_select_clause()?;
        let from_clause = self.parse_from_clause()?;
        let where_clause = self.parse_where_clause()?;
        let group_by_clause = self.parse_group_by_clause()?;
        let having_clause = self.parse_having_clause()?;
        let order_by_clause = self.parse_order_by_clause()?;
        let limit_clause = self.parse_limit_clause()?;
        let offset_clause = self.parse_offset_clause()?;
        Ok(ast::Statement::Select {
            select_clause,
            from_clause,
            where_clause,
            group_by_clause,
            having_clause,
            order_by_clause,
            limit_clause,
            offset_clause,
        })
    }

    /// Parses a SELECT clause, if present.
    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut select = Vec::new();
        let mut first = true;
        while !self.next_is(Token::Keyword(Keyword::From))
            && !self.next_is(Token::Keyword(Keyword::Where))
            && !self.next_is(Token::Keyword(Keyword::Group))
            && !self.next_is(Token::Keyword(Keyword::Order))
            && !self.next_is(Token::Keyword(Keyword::Limit))
            && !self.next_is(Token::Keyword(Keyword::Offset))
            && !self.next_is(Token::Semicolon)
        {
            if !first {
                self.expect(Token::Comma)?;
            }
            first = false;
            let expr = self.parse_expression()?;
            let alias = if self.next_is(Token::Keyword(Keyword::As)) {
                Some(self.next_ident()?)
            } else {
                None
            };
            select.push((expr, alias));
        }
        Ok(select)
    }

    /// Parses a FROM clause, if present.
    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        let mut from = Vec::new();
        self.expect(Token::Keyword(Keyword::From))?;
        loop {
            from.push(self.parse_from_table()?);
            if let Some(join_type) = self.parse_from_join()? {
                from.push(ast::From::Join {
                    left: Box::new(from.pop().unwrap()),
                    join_type,
                    right: Box::new(self.parse_from_table()?),
                    condition: self.parse_where_clause()?,
                });
            } else {
                break;
            }
        }
        Ok(from)
    }

    // Parses a FROM table.
    fn parse_from_table(&mut self) -> Result<ast::From> {
        let table = self.next_ident()?;
        let alias = if self.next_is(Token::Keyword(Keyword::As)) {
            Some(self.next_ident()?)
        } else {
            None
        };
        Ok(ast::From::Table { table, alias })
    }

    // Parses a FROM JOIN type, if present.
    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Inner => {
                    self.expect(Token::Keyword(Keyword::Join))?;
                    Ok(Some(ast::JoinType::Inner))
                }
                Keyword::Left => {
                    self.expect(Token::Keyword(Keyword::Join))?;
                    Ok(Some(ast::JoinType::Left))
                }
                Keyword::Right => {
                    self.expect(Token::Keyword(Keyword::Join))?;
                    Ok(Some(ast::JoinType::Right))
                }
                Keyword::Cross => {
                    self.expect(Token::Keyword(Keyword::Join))?;
                    Ok(Some(ast::JoinType::Cross))
                }
                _ => Err(errinput!("unexpected keyword {}", kw)),
            }
        } else {
            Ok(None)
        }
    }

    /// Parses a WHERE clause, if present.
    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Where)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses a GROUP BY clause, if present.
    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        let mut group_by = Vec::new();
        self.expect(Token::Keyword(Keyword::Group))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut first = true;
        while !self.next_is(Token::Keyword(Keyword::Having))
            && !self.next_is(Token::Keyword(Keyword::Order))
            && !self.next_is(Token::Keyword(Keyword::Limit))
            && !self.next_is(Token::Keyword(Keyword::Offset))
            && !self.next_is(Token::Semicolon)
        {
            if !first {
                self.expect(Token::Comma)?;
            }
            first = false;
            group_by.push(self.parse_expression()?);
        }
        Ok(group_by)
    }

    /// Parses a HAVING clause, if present.
    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Having)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an ORDER BY clause, if present.
    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        let mut order_by = Vec::new();
        self.expect(Token::Keyword(Keyword::Order))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut first = true;
        while !self.next_is(Token::Keyword(Keyword::Limit))
            && !self.next_is(Token::Keyword(Keyword::Offset))
            && !self.next_is(Token::Semicolon)
        {
            if !first {
                self.expect(Token::Comma)?;
            }
            first = false;
            let expr = self.parse_expression()?;
            let direction = if self.next_is(Token::Keyword(Keyword::Asc)) {
                ast::Direction::Asc
            } else if self.next_is(Token::Keyword(Keyword::Desc)) {
                ast::Direction::Desc
            } else {
                ast::Direction::Asc
            };
            order_by.push((expr, direction));
        }
        Ok(order_by)
    }

    /// Parses a LIMIT clause, if present.
    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Limit)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an OFFSET clause, if present.
    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Offset)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses a data type.
    fn parse_data_type(&mut self) -> Result<DataType> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Bool | Keyword::Boolean => Ok(DataType::Bool),
                Keyword::Int | Keyword::Integer => Ok(DataType::Int),
                Keyword::Double => Ok(DataType::Double),
                Keyword::String | Keyword::Text => Ok(DataType::String),
                Keyword::Time => Ok(DataType::Time),
                Keyword::Varchar => {
                    self.expect(Token::OpenParen)?;
                    let len = self.parse_expression()?;
                    self.expect(Token::CloseParen)?;
                    Ok(DataType::Varchar(Box::new(len)))
                }
                _ => Err(errinput!("unexpected keyword {}", kw)),
            }
        } else {
            Err(errinput!("expected data type"))
        }
    }

    /// Parses an expression using the precedence climbing algorithm.
    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(Precedence::Lowest)
    }

    /// Parses an expression at the given minimum precedence.
    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
        let mut lhs = self.parse_expression_atom()?;
        loop {
            if let Some(op) = self.parse_prefix_operator_at(min_precedence) {
                lhs = op.into_expression(lhs);
                continue;
            }
            if let Some(op) = self.parse_infix_operator_at(min_precedence) {
                let rhs = self.parse_expression_at(op.precedence() + op.associativity())?;
                lhs = op.into_expression(lhs, rhs);
                continue;
            }
            if let Some(op) = self.parse_postfix_operator_at(min_precedence)? {
                lhs = op.into_expression(lhs);
                continue;
            }
            break;
        }
        Ok(lhs)
    }

    /// Parses an expression atom.
    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::True => return Ok(ast::Expression::Literal(ast::Literal::Boolean(true))),
                Keyword::False => return Ok(ast::Expression::Literal(ast::Literal::Boolean(false))),
                Keyword::Null => return Ok(ast::Expression::Literal(ast::Literal::Null)),
                Keyword::Infinity => return Ok(ast::Expression::Literal(ast::Literal::Double(f64::INFINITY))),
                Keyword::NaN => return Ok(ast::Expression::Literal(ast::Literal::Double(f64::NAN))),
                Keyword::Now => {
                    self.expect(Token::OpenParen)?;
                    self.expect(Token::CloseParen)?;
                    return Ok(ast::Expression::Function {
                        name: "now".to_string(),
                        args: vec![],
                    });
                }
                _ => {}
            }
        }
        if let Some(t) = self.next_if(|t| matches!(t, Token::Number(_))) {
            if let Token::Number(s) = t {
                if s.contains('.') || s.contains('e') || s.contains('E') {
                    if let Ok(v) = s.parse::<f64>() {
                        return Ok(ast::Expression::Literal(ast::Literal::Double(v)));
                    }
                }
                if let Ok(v) = s.parse::<i64>() {
                    return Ok(ast::Expression::Literal(ast::Literal::Int(v)));
                }
            }
        }
        if let Some(t) = self.next_if(|t| matches!(t, Token::String(_))) {
            if let Token::String(s) = t {
                return Ok(ast::Expression::Literal(ast::Literal::String(s)));
            }
        }
        if let Some(t) = self.next_if(|t| matches!(t, Token::Ident(_))) {
            if let Token::Ident(s) = t {
                if self.next_is(Token::OpenParen) {
                    let mut args = Vec::new();
                    let mut first = true;
                    while !self.next_is(Token::CloseParen) {
                        if !first {
                            self.expect(Token::Comma)?;
                        }
                        first = false;
                        args.push(self.parse_expression()?);
                    }
                    self.expect(Token::CloseParen)?;
                    return Ok(ast::Expression::Function { name: s, args });
                }
                return Ok(ast::Expression::Column(s));
            }
        }
        if self.next_is(Token::OpenParen) {
            let expr = self.parse_expression()?;
            self.expect(Token::CloseParen)?;
            return Ok(expr);
        }
        Err(errinput!("expected expression"))
    }

    /// Parses a prefix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_prefix_operator_at(&mut self, min_precedence: Precedence) -> Option<PrefixOperator> {
        if self.next_is(Token::Minus) {
            Some(PrefixOperator::Minus)
        } else if self.next_is(Token::Keyword(Keyword::Not)) {
            Some(PrefixOperator::Not)
        } else if self.next_is(Token::Plus) {
            Some(PrefixOperator::Plus)
        } else {
            None
        }
    }

    /// Parses an infix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_infix_operator_at(&mut self, min_precedence: Precedence) -> Option<InfixOperator> {
        if self.next_is(Token::Plus) {
            Some(InfixOperator::Add)
        } else if self.next_is(Token::Minus) {
            Some(InfixOperator::Subtract)
        } else if self.next_is(Token::Asterisk) {
            Some(InfixOperator::Multiply)
        } else if self.next_is(Token::Slash) {
            Some(InfixOperator::Divide)
        } else if self.next_is(Token::Caret) {
            Some(InfixOperator::Exponentiate)
        } else if self.next_is(Token::Percent) {
            Some(InfixOperator::Remainder)
        } else if self.next_is(Token::Equal) {
            Some(InfixOperator::Equal)
        } else if self.next_is(Token::NotEqual) {
            Some(InfixOperator::NotEqual)
        } else if self.next_is(Token::LessOrGreaterThan) {
            Some(InfixOperator::NotEqual)
        } else if self.next_is(Token::LessThan) {
            Some(InfixOperator::LessThan)
        } else if self.next_is(Token::LessThanOrEqual) {
            Some(InfixOperator::LessThanOrEqual)
        } else if self.next_is(Token::GreaterThan) {
            Some(InfixOperator::GreaterThan)
        } else if self.next_is(Token::GreaterThanOrEqual) {
            Some(InfixOperator::GreaterThanOrEqual)
        } else if self.next_is(Token::Keyword(Keyword::And)) {
            Some(InfixOperator::And)
        } else if self.next_is(Token::Keyword(Keyword::Or)) {
            Some(InfixOperator::Or)
        } else if self.next_is(Token::Keyword(Keyword::Like)) {
            Some(InfixOperator::Like)
        } else {
            None
        }
    }

    /// Parses a postfix operator, if there is one and its precedence is at
    /// least min_precedence.
    fn parse_postfix_operator_at(
        &mut self,
        min_precedence: Precedence,
    ) -> Result<Option<PostfixOperator>> {
        if self.next_is(Token::Exclamation) {
            Ok(Some(PostfixOperator::Factorial))
        } else if self.next_is(Token::Keyword(Keyword::Is)) {
            if self.next_is(Token::Keyword(Keyword::Not)) {
                if self.next_is(Token::Keyword(Keyword::Null)) {
                    return Ok(Some(PostfixOperator::IsNot(ast::Literal::Null)));
                }
                if self.next_is(Token::Keyword(Keyword::NaN)) {
                    return Ok(Some(PostfixOperator::IsNot(ast::Literal::Double(f64::NAN))));
                }
                return Err(errinput!("expected NULL or NaN after IS NOT"));
            }
            if self.next_is(Token::Keyword(Keyword::Null)) {
                return Ok(Some(PostfixOperator::Is(ast::Literal::Null)));
            }
            if self.next_is(Token::Keyword(Keyword::NaN)) {
                return Ok(Some(PostfixOperator::Is(ast::Literal::Double(f64::NAN))));
            }
            return Err(errinput!("expected NULL or NaN after IS"));
        }
        Ok(None)
    }
}
