   282	        let where_clause = self.parse_where_clause()?;
   283	        let group_by_clause = self.parse_group_by_clause()?;
   284	        let having_clause = self.parse_having_clause()?;
   285	        let order_by_clause = self.parse_order_by_clause()?;
   286	        let limit_clause = self.parse_limit_clause()?;
   287	        let offset_clause = self.parse_offset_clause()?;
   288	        Ok(ast::Statement::Select {
   289	            select_clause,
   290	            from_clause,
   291	            where_clause,
   292	            group_by_clause,
   293	            having_clause,
   294	            order_by_clause,
   295	            limit_clause,
   296	            offset_clause,
   297	        })
