   300	    /// Parses a SELECT clause, if present.
   301	    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
   302	        let mut select = Vec::new();
   303	        let mut first = true;
   304	        while !self.next_is(Token::Keyword(Keyword::From))
   305	            && !self.next_is(Token::Keyword(Keyword::Where))
   306	            && !self.next_is(Token::Keyword(Keyword::Group))
   307	            && !self.next_is(Token::Keyword(Keyword::Order))
   308	            && !self.next_is(Token::Keyword(Keyword::Limit))
   309	            && !self.next_is(Token::Keyword(Keyword::Offset))
   310	            && !self.next_is(Token::Semicolon)
   311	        {
   312	            if !first {
   313	                self.expect(Token::Comma)?;
   314	            }
   315	            first = false;
   316	            let expr = self.parse_expression()?;
   317	            let alias = if self.next_is(Token::Keyword(Keyword::As)) {
   318	                Some(self.next_ident()?)
   319	            } else {
   320	                None
   321	            };
