   347	    // Parses a FROM table.
   348	    fn parse_from_table(&mut self) -> Result<ast::From> {
   349	        let table = self.next_ident()?;
   350	        let alias = if self.next_is(Token::Keyword(Keyword::As)) {
   351	            Some(self.next_ident()?)
   352	        } else {
   353	            None
   354	        };
