   365	                }
   366	                Keyword::Left => {
   367	                    self.expect(Token::Keyword(Keyword::Join))?;
   368	                    Ok(Some(ast::JoinType::Left))
   369	                }
   370	                Keyword::Right => {
   371	                    self.expect(Token::Keyword(Keyword::Join))?;
   372	                    Ok(Some(ast::JoinType::Right))
   373	                }
